const $ = s => document.querySelector(s);
if ('scrollRestoration' in history) history.scrollRestoration='manual';
const icons={terminal:'<path d="m5 7 5 5-5 5m8 0h6"/><rect x="2" y="3" width="20" height="18" rx="3"/>',server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.1M7 17.5h.1M12 6.5h5M12 17.5h5"/>',network:'<rect x="9" y="2" width="6" height="6" rx="1"/><rect x="2" y="16" width="6" height="6" rx="1"/><rect x="16" y="16" width="6" height="6" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',cube:'<path d="m12 2 9 5v10l-9 5-9-5V7Zm0 10 9-5M12 12 3 7m9 5v10M7.5 4.5l9 5v5"/>',pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4M18 9h4m-4 6h4"/>',layers:'<path d="m12 2 10 5-10 5L2 7Zm-10 10 10 5 10-5M2 17l10 5 10-5"/>',flask:'<path d="M9 2h6M10 2v7L4 19a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3L14 9V2M7 15h10"/>',book:'<path d="M12 5c-3-2-6-2-10-1v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v16"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
function writeStore(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}
let progress=readStore('cloudinfra-progress',{}); if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};
let checks=readStore('cloudinfra-checks',{}); if(!checks||typeof checks!=='object'||Array.isArray(checks))checks={};
let filter='all',observer,searchIndex=-1,searchItems=[],toastTimer;
const ordered=modules.flatMap(m=>articles.filter(a=>a.module===m.id));
const moduleFor=id=>modules.find(m=>m.id===id);
const countRead=()=>ordered.filter(a=>progress[a.id]).length;
const tags=items=>`<div class="tag-row">${items.map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join('')}</div>`;
const articleURL=id=>`#/article/${id}`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
const footer=()=>`<footer class="footer"><div class="container"><span>© 2026 CloudInfra Guide · 从理解原理，到构建系统。</span><span>原创入门内容 · <a href="#/about">关于本站</a> · <a href="#/roadmap">学习路线</a></span></div></footer>`;
function moduleCard(m){const n=articles.filter(a=>a.module===m.id).length;return `<a href="#/module/${m.id}" class="module-card ${m.featured?'featured':''}"><div class="card-top"><span class="module-icon">${icon(m.icon)}</span>${m.featured?'<span class="small-badge">AI 训练主线</span>':`<span class="card-number">${m.n}</span>`}</div><h3>${m.name}</h3><p>${m.desc}</p>${tags(m.tags)}<div class="card-footer"><span>${n} 篇入门文章</span><b>开始阅读 ↗</b></div></a>`}
function renderModuleGrid(){const list=filter==='ai'?modules.filter(m=>['network','training','platform','practice'].includes(m.id)):modules;$('#module-grid').innerHTML=list.map(moduleCard).join('');document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)})}
function home(){document.title='CloudInfra Guide · 云计算与 AI 基础设施';$('#app').innerHTML=`<main id="main" class="container" tabindex="-1"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> THE CLOUD ENGINEER'S FIELD GUIDE</div><h1>CloudInfra <em>Guide</em><span class="cn-title">从云计算，到 AI 基础设施。</span></h1><p>系统学习云计算、云原生与 SRE，<br>深入 GPU 集群、分布式训练与 AI 平台工程。<br>把分散的知识，连成真正可用的工程能力。</p><div class="buttons"><a class="btn" href="${articleURL('cloud-overview')}">开始学习 <span>→</span></a><a class="btn secondary" href="#/roadmap">查看学习路线 <span>↗</span></a></div><div class="hero-meta"><span>${icon('book')}8 个知识模块</span><span>${icon('layers')}12 篇入门文章</span><span>${icon('check')}原理 × 工程实践</span></div></div><div class="stack-map"><div class="map-label"><span>YOUR INFRASTRUCTURE STACK</span><span>由底向上，逐层理解 ↗</span></div><a class="map-layer accent" href="#/module/training">${icon('chip')}<div><strong>AI 训练与平台工程</strong><small>GPU · DISTRIBUTED TRAINING · SCHEDULING</small></div><span class="layer-no">04</span></a><div class="map-connector">↑</div><a class="map-layer" href="#/module/sre">${icon('pulse')}<div><strong>可靠性与可观测性</strong><small>SLO · METRICS · INCIDENT RESPONSE</small></div><span class="layer-no">03</span></a><div class="map-connector">↑</div><a class="map-layer" href="#/module/native">${icon('cube')}<div><strong>云原生与应用交付</strong><small>CONTAINERS · KUBERNETES · CI/CD</small></div><span class="layer-no">02</span></a><div class="map-connector">↑</div><a class="map-layer" href="#/module/compute">${icon('server')}<div><strong>计算、网络与存储</strong><small>COMPUTE · NETWORK · STORAGE</small></div><span class="layer-no">01</span></a><div class="map-caption">一张知识地图，连接云与 AI 的工程世界</div></div></section><div class="path-strip"><strong>建议学习路径</strong><a href="#/module/foundation"><i>01</i>基础认知</a><span class="arrow">→</span><a href="#/module/compute"><i>02</i>云上资源</a><span class="arrow">→</span><a href="#/module/native"><i>03</i>云原生</a><span class="arrow">→</span><a href="#/module/sre"><i>04</i>可靠性</a><span class="arrow">→</span><a href="#/module/training"><i>05</i>AI 训练</a></div><section class="section"><div class="section-heading"><div><h2>知识库</h2><p>建立完整知识体系，也可以从你正在解决的问题出发。</p></div><div class="view-tabs" aria-label="知识库筛选"><button data-filter="all" class="active" aria-pressed="true">全部模块</button><button data-filter="ai" aria-pressed="false">AI 训练路径</button></div></div><div class="module-grid" id="module-grid"></div></section><section class="ai-feature"><div><div class="eyebrow">FOCUS / CLOUD × AI</div><h2>让云上的每一张 GPU，<br>都更接近有效训练。</h2><p>从算力、通信、数据到恢复机制，<br>用系统视角理解一次训练任务的完整生命周期。</p><a class="feature-link" href="${articleURL('gpu-cluster')}">进入云上训练专题 →</a></div><div class="feature-list">${['gpu-cluster','distributed-training','training-lab'].map((id,i)=>{let a=articles.find(a=>a.id===id);return `<a href="${articleURL(id)}"><span>0${i+1}</span>${a.title}<b>↗</b></a>`}).join('')}</div></section><section class="section"><div class="section-heading"><div><h2>从这些文章开始</h2><p>先建立全局认知，再深入具体的工程问题。</p></div><a href="#/roadmap">完整学习路线 →</a></div><div class="recent-list">${['cloud-overview','gpu-cluster','incident'].map(id=>{let a=articles.find(a=>a.id===id);return `<a class="recent-row" href="${articleURL(id)}"><span class="recent-cat">${moduleFor(a.module).name}</span><div><h3>${a.title}</h3><p>${a.desc}</p></div><span class="level">${a.level}</span><b>↗</b></a>`}).join('')}</div></section></main>${footer()}`;renderModuleGrid()}
function sidebar(moduleId,current){return `<aside class="sidebar" aria-label="章节导航"><a class="side-home" href="#/">← 返回知识库</a><div class="side-heading"><span>学习目录 / CONTENTS</span><span>12</span></div>${modules.map(m=>`<details ${m.id===moduleId?'open':''}><summary><span>${m.n}</span>${m.name}</summary><div class="side-links"><a href="#/module/${m.id}" ${!current&&moduleId===m.id?'class="current" aria-current="page"':''}>模块概览</a>${articles.filter(a=>a.module===m.id).map(a=>`<a href="${articleURL(a.id)}" ${current===a.id?'class="current" aria-current="page"':''}>${a.number} ${a.title}${progress[a.id]?'<span class="read-mark">✓</span>':''}</a>`).join('')}</div></details>`).join('')}<div class="side-progress"><div><span>我的阅读进度</span><b>${countRead()} / ${articles.length}</b></div><div class="progress-bar"><span style="width:${countRead()/articles.length*100}%"></span></div><span>仅保存在当前浏览器</span></div></aside>`}
function breadcrumbs(m,end=''){return `<div class="breadcrumb"><a href="#/">知识库</a><span>／</span><a href="#/module/${m.id}">${m.name}</a>${end?`<span>／</span><span>${end}</span>`:''}</div>`}
function modulePage(m){document.title=`${m.name} · CloudInfra Guide`;const list=articles.filter(a=>a.module===m.id);$('#app').innerHTML=`<main class="doc-layout" id="main" tabindex="-1">${sidebar(m.id)}<article class="article">${breadcrumbs(m)}<div class="eyebrow">MODULE ${m.n} / ${m.en}</div><h1 style="margin-top:18px">${m.name}</h1><p class="description">${m.desc}</p>${tags(m.tags)}<div class="module-intro">本模块包含 ${list.length} 篇入门文章。建议按顺序阅读，完成文末自我检验，再进入相关实战。</div>${list.map(a=>`<a class="chapter-row" href="${articleURL(a.id)}"><div class="chapter-top"><span>CHAPTER ${a.number}</span><span>${a.level} · ${progress[a.id]?'已读 ✓':'开始阅读 ↗'}</span></div><h2>${a.title}</h2><p>${a.desc}</p></a>`).join('')}<div class="callout"><strong>学习建议</strong><p>把概念与实际系统对应起来：画出数据路径，写下观测指标，再设计一次小规模实验。</p></div><a class="btn secondary" href="#/roadmap">查看完整学习路线 →</a></article><aside class="toc"><div class="toc-title">本模块</div>${list.map(a=>`<a href="${articleURL(a.id)}">${a.number} ${a.title}</a>`).join('')}<div class="toc-note">先理解原理，再验证假设。</div></aside></main>${footer()}`}
function articlePage(a,anchor){const m=moduleFor(a.module),idx=ordered.indexOf(a),prev=ordered[idx-1],next=ordered[idx+1];document.title=`${a.title} · CloudInfra Guide`;$('#app').innerHTML=`<main class="doc-layout" id="main" tabindex="-1">${sidebar(a.module,a.id)}<article class="article">${breadcrumbs(m,a.number)}<div class="article-meta"><span class="category">${m.name}</span><span>${a.level}</span><span>·</span><span>初版 · 2026.11.03</span></div><h1>${a.number} ${a.title}</h1><p class="description">${a.desc}</p>${tags(a.tags)}<p class="intro">${a.intro}</p>${a.sections.map((s,i)=>`<section class="article-section" id="section-${i+1}"><h2><span class="section-index">${String(i+1).padStart(2,'0')}</span>${s[0]}</h2>${s[1]}</section>`).join('')}<section class="article-section" id="self-check"><h2><span class="section-index">✓</span>自我检验</h2><div class="checklist">${a.check.map((c,i)=>`<label><input type="checkbox" data-check="${a.id}:${i}" ${checks[`${a.id}:${i}`]?'checked':''}>${c}</label>`).join('')}<small>勾选代表自我评估，进度仅保存在当前浏览器。</small></div></section><section class="article-section references" id="references"><h2><span class="section-index">↗</span>参考资料</h2>${a.refs.map(r=>`<a href="${sources[r][1]}" target="_blank" rel="noopener noreferrer">${sources[r][0]} ↗</a>`).join('')}</section><div class="completion"><span>把理解变成能力：画出来、讲清楚、做一次实验。</span><button class="read-btn ${progress[a.id]?'done':''}" data-read="${a.id}">${progress[a.id]?'✓ 已读 · 点击取消':'标记为已读'}</button></div><nav class="article-nav" aria-label="相邻文章">${prev?`<a href="${articleURL(prev.id)}"><small>← 上一篇</small>${prev.title}</a>`:'<a href="#/roadmap"><small>← 开始之前</small>完整学习路线</a>'}${next?`<a href="${articleURL(next.id)}"><small>下一篇 →</small>${next.title}</a>`:'<a href="#/"><small>完成本轮阅读 →</small>返回知识库</a>'}</nav></article><aside class="toc"><div class="toc-title">本文目录 / ON THIS PAGE</div>${a.sections.map((s,i)=>`<a data-toc="section-${i+1}" href="${articleURL(a.id)}?section=${i+1}">${i+1}. ${s[0]}</a>`).join('')}<a data-toc="self-check" href="${articleURL(a.id)}?section=self-check">自我检验</a><a data-toc="references" href="${articleURL(a.id)}?section=references">参考资料</a><div class="toc-note">${icon('book')} 阅读 · 理解 · 实践</div></aside></main>${footer()}`;initInteractive();observeSections();if(anchor)requestAnimationFrame(()=>document.getElementById(/^\d+$/.test(anchor)?`section-${anchor}`:anchor)?.scrollIntoView())}
function observeSections(){observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){document.querySelectorAll('[data-toc]').forEach(a=>a.classList.toggle('active',a.dataset.toc===e.target.id));break}}},{rootMargin:'-90px 0px -60% 0px',threshold:0});document.querySelectorAll('.article-section').forEach(s=>observer.observe(s))}
function roadmap(){document.title='学习路线 · CloudInfra Guide';const stages=[['基础认知','理解资源、网络与数据流，能画出一个云应用的结构。',['cloud-overview','cloud-compute','vpc-network','training-storage']],['云原生与交付','理解期望状态、工作负载生命周期，让部署可以追踪。',['kubernetes-basics','delivery']],['可靠性与排障','定义目标，建立观测与证据，能解释系统为何出现异常。',['slo','incident']],['云上 AI 训练','从单卡走向多机，理解显存、通信与扩展效率。',['gpu-cluster','distributed-training']],['平台工程与实战','连接任务、资源和数据，设计可恢复的训练流程。',['training-platform','training-lab']]];$('#app').innerHTML=`<main class="doc-layout" id="main" tabindex="-1">${sidebar()}<article class="article"><div class="breadcrumb"><a href="#/">知识库</a><span>／ 学习路线</span></div><div class="eyebrow">LEARN WITH A SYSTEMS MINDSET</div><h1 style="margin-top:18px">一条路，连接云与 AI。</h1><p class="description">按知识依赖逐步前进。已有云基础，可以直接从第四阶段进入训练主线。</p><div class="module-intro">已读 ${countRead()} / ${articles.length} 篇 · 不以读完为终点，以能够解释和验证为目标。</div>${stages.map((s,i)=>`<section class="roadmap-step"><span class="step-num">0${i+1}</span><div><h2>${s[0]}</h2><p>${s[1]}</p>${s[2].map(id=>{let a=articles.find(x=>x.id===id);return `<a href="${articleURL(id)}">${a.number} ${a.title} ${progress[id]?'✓':'↗'}</a>`}).join('')}</div></section>`).join('')}</article></main>${footer()}`}
function about(){document.title='关于 · CloudInfra Guide';$('#app').innerHTML=`<main id="main" class="container article" style="max-width:800px" tabindex="-1"><div class="breadcrumb"><a href="#/">知识库</a><span>／ 关于</span></div><h1>关于 CloudInfra Guide</h1><p class="description">从云计算基础，到训练系统的工程实践。</p><section class="article-section"><h2>内容定位</h2><p>本站是第一版中文学习原型，包含 8 个模块、12 篇原创入门文章。云计算、云原生与 SRE 构成基础，云上 AI 训练和平台工程构成进阶主线。它提供概念框架与设计练习，尚不等同于完整的生产部署教程。</p><h2>阅读方式</h2><p>从学习路线进入，每篇文章提供原理、工程场景、自我检验和官方参考资料。搜索支持标题、标签与正文。阅读进度、主题与勾选只保存在当前浏览器。</p><h2>结构参考</h2><p>本站借鉴 <a style="color:var(--blue)" href="https://caomaolufei.github.io/AIInfraGuide/" target="_blank" rel="noopener noreferrer">AIInfraGuide ↗</a> 的专题导航、章节树、正文与页内目录组织。云计算与训练内容为本原型原创，未复制参考站文章、图片或品牌。</p><h2>后续可扩展专题</h2><p>Linux 与网络实验、IaC、云安全、多云架构、GPU 资源池、RDMA、FSDP 实验、训练性能剖析、模型与数据版本管理。正式发布教程时，应补充环境版本、完整代码和可复现结果。</p></section><a href="#/" class="btn secondary">返回知识库 →</a></main>${footer()}`}
let currentPath='';
function route(){const hash=location.hash.slice(1)||'/',[path,query]=hash.split('?'),parts=path.split('/').filter(Boolean),anchor=new URLSearchParams(query||'').get('section');if(path===currentPath&&parts[0]==='article'&&anchor){document.getElementById(/^\d+$/.test(anchor)?`section-${anchor}`:anchor)?.scrollIntoView();return}currentPath=path;observer?.disconnect();$('#search-dialog').close();$('.top-nav').classList.remove('mobile-open');$('#mobile-menu').setAttribute('aria-expanded','false');document.querySelectorAll('.top-nav a').forEach(a=>a.classList.remove('active'));window.scrollTo({top:0,left:0,behavior:'instant'});if(!parts.length)home();else if(parts[0]==='module'&&moduleFor(parts[1])){modulePage(moduleFor(parts[1]));document.querySelector(`.top-nav a[href="#/module/${parts[1]}"]`)?.classList.add('active')}else if(parts[0]==='article'&&articles.find(a=>a.id===parts[1])){const a=articles.find(a=>a.id===parts[1]);articlePage(a,anchor);document.querySelector(`.top-nav a[href="#/module/${a.module}"]`)?.classList.add('active')}else if(parts[0]==='roadmap')roadmap();else if(parts[0]==='about')about();else{$('#app').innerHTML=`<main id="main" class="not-found" tabindex="-1"><h1>没有找到这个章节</h1><p>你可以返回知识库，或搜索相关内容。</p><a class="btn" href="#/">返回知识库</a></main>`;document.title='章节未找到 · CloudInfra Guide'}$('#main')?.focus({preventScroll:true})}
function initInteractive(){if($('#topology-demo')){let mode=0;const render=()=>{const info=[['单卡训练','一张 GPU 承载训练：先关注显存容量、算子效率与数据输入。'],['单机多卡','多张 GPU 在同一节点协作：新增梯度同步、数据分片与机内互联问题。'],['多机多卡','跨节点通信成为关键路径之一：同时验证网络、拓扑、任务协调与整体恢复。']];const node=(n,c)=>`<div class="gpu-node"><small>NODE ${n}</small><div class="gpu-chips">${Array.from({length:c},(_,i)=>`<span>GPU ${i}</span>`).join('')}</div></div>`;$('#topology-demo').innerHTML=`<div class="interactive"><div class="segmented" aria-label="训练拓扑">${info.map((x,i)=>`<button data-topology="${i}" class="${i===mode?'active':''}" aria-pressed="${i===mode}">${x[0]}</button>`).join('')}</div><div class="topology-nodes">${node('A',mode?2:1)}${mode===2?'<div class="network-bridge">⇄<br>节点间网络</div>'+node('B',2):''}</div><p class="demo-caption" aria-live="polite">${info[mode][1]}</p></div>`;$('#topology-demo').querySelectorAll('button').forEach(b=>b.onclick=()=>{mode=Number(b.dataset.topology);render()})};render()}
if($('#scaling-demo')){$('#scaling-demo').innerHTML=`<div class="interactive"><div class="calc-fields"><label>单卡吞吐（样本/秒）<input id="base-throughput" type="number" min="0.01" step="any" value="100"></label><label>多卡吞吐（样本/秒）<input id="multi-throughput" type="number" min="0.01" step="any" value="620"></label><label>GPU 数量<input id="gpu-count" type="number" min="1" max="100000" step="1" value="8"></label></div><div id="calc-result" aria-live="polite"></div></div>`;const calc=()=>{const a=Number($('#base-throughput').value),b=Number($('#multi-throughput').value),n=Number($('#gpu-count').value);$('#calc-result').innerHTML=(!Number.isFinite(a)||!Number.isFinite(b)||a<=0||b<=0||!Number.isInteger(n)||n<1||n>100000)?'<p class="calc-error">请输入正数吞吐和有效的整数 GPU 数量。</p>':`<div class="calc-output"><div><strong>${(b/a).toFixed(2)}×</strong><small>吞吐加速比</small></div><div><strong>${(b/a/n*100).toFixed(1)}%</strong><small>扩展效率</small></div></div>${b/a/n>1?'<p class="demo-caption">效率超过 100%，请检查比较口径；缓存和工作负载变化也可能带来超线性结果。</p>':''}`};document.querySelectorAll('.calc-fields input').forEach(i=>i.addEventListener('input',calc));calc()}}
function search(q=''){const query=q.trim().toLowerCase();searchItems=ordered.filter(a=>!query||[a.title,a.desc,...a.tags,a.intro,...a.sections.flat()].join(' ').toLowerCase().includes(query));searchIndex=-1;$('#search-results').innerHTML=searchItems.length?searchItems.map(a=>`<a class="search-result" href="${articleURL(a.id)}"><small>${moduleFor(a.module).name} · ${a.number}</small><strong>${a.title}</strong><p>${a.desc}</p></a>`).join(''):`<p class="search-empty">没有找到相关内容。试试「GPU」「网络」或「Checkpoint」。</p>`}
function openSearch(){$('#search-dialog').showModal();$('#search-input').value='';search();$('#search-input').focus()}
$('#search-open').onclick=openSearch;$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-input').addEventListener('input',e=>search(e.target.value));$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog'))$('#search-dialog').close();if(e.target.closest('.search-result'))$('#search-dialog').close()});
$('#search-input').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!searchItems.length)return;searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+searchItems.length)%searchItems.length;document.querySelectorAll('.search-result').forEach((a,i)=>{a.classList.toggle('selected',i===searchIndex);if(i===searchIndex)a.scrollIntoView({block:'nearest'})})}else if(e.key==='Enter'&&searchItems.length){e.preventDefault();location.hash=articleURL(searchItems[Math.max(0,searchIndex)].id);$('#search-dialog').close()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#search-dialog').open)$('#search-dialog').close();else openSearch()}});
function applyTheme(dark){document.documentElement.classList.toggle('dark',dark);$('#theme').setAttribute('aria-label',dark?'切换浅色模式':'切换深色模式')}
applyTheme(readStore('cloudinfra-dark',false)===true);$('#theme').onclick=()=>{const dark=!document.documentElement.classList.contains('dark');applyTheme(dark);writeStore('cloudinfra-dark',dark)};
$('#mobile-menu').onclick=()=>{const open=$('.top-nav').classList.toggle('mobile-open');$('#mobile-menu').setAttribute('aria-expanded',open)};
document.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;renderModuleGrid()}const r=e.target.closest('[data-read]');if(r){progress[r.dataset.read]=!progress[r.dataset.read];const saved=writeStore('cloudinfra-progress',progress);r.classList.toggle('done',progress[r.dataset.read]);r.textContent=progress[r.dataset.read]?'✓ 已读 · 点击取消':'标记为已读';const a=articles.find(a=>a.id===r.dataset.read);$('.sidebar').outerHTML=sidebar(a.module,a.id);toast(saved?(progress[a.id]?'已保存阅读进度':'已取消已读标记'):'本次进度已更新，浏览器存储不可用')}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){checks[e.target.dataset.check]=e.target.checked;if(!writeStore('cloudinfra-checks',checks))toast('浏览器存储不可用，勾选仅在本次会话保留')}});
$('.skip').onclick=e=>{e.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView()};
window.addEventListener('hashchange',route);route();
